1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: unknown[];
4	};
5	
6	export type ScenarioResult = {
7	  results: unknown[];
8	};
9	
10	export const runScenario = (scenario: Scenario): ScenarioResult => {
11	  return { results: scenario.steps.map(() => ({ premium: 5 })) };
12	};
