1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Edge case: empty policy ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result.results).toEqual([{ premium: 5 }]);
13	  });
14	
15	  // --- Base premiums for main items (with first-insurance surcharge and fee) ---
16	  it.todo("a single plain sword for a new customer → 100 G base + 10 G first insurance + 5 G fee = 115 G");
17	  it.todo("a single plain amulet for a new customer → 60 G base + 6 G first insurance + 5 G fee = 71 G");
18	  it.todo("a single plain staff for a new customer → 80 G base + 8 G first insurance + 5 G fee = 93 G");
19	  it.todo("a single plain potion for a new customer → 40 G base + 4 G first insurance + 5 G fee = 49 G");
20	
21	  // --- Components and building blocks ---
22	  it.todo("2 runes → 50 G base premium");
23	  it.todo("3 runes → 60 G base premium (block of 3 alike components applies)");
24	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
25	  it.todo("7 runes → 175 G base premium");
26	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
27	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
28	
29	  // --- Item-level modifiers ---
30	  it.todo("a cursed sword → 50 % risk surcharge on its base premium (100 G → 150 G)");
31	  it.todo("a sword with enchantment 5 → 30 % high-enchantment surcharge applies (100 G → 130 G)");
32	  it.todo("a sword with enchantment 4 → no high-enchantment surcharge (100 G base)");
33	  it.todo("a cursed sword with enchantment 5 → both surcharges apply (100 G → 180 G)");
34	
35	  // --- Modifier scope on multi-item policies ---
36	  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee");
37	
38	  // --- Policy-level modifiers ---
39	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
40	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
41	  it.todo("every quote carries the 10 % first insurance surcharge, regardless of customer history");
42	  it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");
43	
44	  // --- Rounding in MHPCO's favor ---
45	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
46	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
47	
48	  // --- Integration examples ---
49	  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 → premium 165 G");
50	  it.todo("3-year customer's second quote of a cursed steel sword, enchantment 7 → premium 160 G");
51	
52	  // --- Claims: standard reimbursement ---
53	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G (damage minus 100 G deductible)");
54	  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
55	
56	  // --- Claims: special clauses ---
57	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
58	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
59	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins over dragon material)");
60	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies, then deductible)");
61	
62	  // --- Claims: deductible per damage event ---
63	  it.todo("a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible applies once per damaged item)");
64	
65	  // --- Claims: insurance sum and cap ---
66	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
67	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
68	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects the premium only)");
69	  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
70	  it.todo("sword insured (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G with remainingCap 600 G, second payout 600 G with remainingCap 0 G");
71	
72	  // --- Multiple items of the same type ---
73	  it.todo("two swords insured, a dragon attack damages both → each damage entry gets its own deductible");
74	
75	  // --- Error cases (CLI exits non-zero, error on stderr) ---
76	  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error, no results");
77	  it.todo("claim references an item not part of the policy (amulet damaged when only a sword is insured) → error");
78	  it.todo("claim references a damage entry with an unknown item type → error");
79	  it.todo("claim contains more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
80	  it.todo("claim contains a damage entry with amount: -200 → error");
81	
82	  // --- CLI ---
83	  it.todo("the CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
84	  it.todo("the CLI exits with a non-zero status code and writes an error description to stderr on an invalid scenario");
85	});
